// Repeats are flattened once per section; visibility then works on units as before.
function sectionFields(sec) {
  if (sec._flat) return sec._flat;
  const out = (sec.fields || []).slice();
  (sec.repeats || []).forEach((rep) => {
    for (let n = 1; n <= rep.max; n++) {
      rep.fields.forEach((f) => {
        out.push({
          ...f,
          key: f.key.replace("%", n),
          label: f.label.replace("%", n),
          needs: f.needs ? f.needs.replace("%", n) : f.needs,
          unit: rep.id + "#" + n,
          unitLabel: rep.label + " " + n,
          repeatOf: rep.id,
          repeatLabel: rep.label,
          repeatKinds: rep.kinds,
          menuGroup: f.menuGroup || rep.menuGroup || null,
        });
      });
    }
  });
  const popup = new Set(out.filter((f) => f.menuGroup === "Popup detail").map(unitOf));
  sec._flat = out.map((f) =>
    (popup.has(unitOf(f)) && !f.advanced) ? { ...f, advanced: true } : f);
  return sec._flat;
}

const unitOf = (f) => f.unit || f.key;

// One entry per unit, in declaration order, for the + menu.
const unitsOf = (sec) => {
  const seen = new Map();
  sectionFields(sec).forEach((f) => {
    const id = unitOf(f);
    if (!seen.has(id)) seen.set(id, { id, label: f.unitLabel || f.label, group: f.menuGroup || null, fields: [] });
    seen.get(id).fields.push(f);
  });
  return [...seen.values()];
};

const dashScopedKeys = () => {
  const out = new Set();
  SECTIONS.forEach((sec) => {
    sectionFields(sec).forEach((f) => {
      if (f.key && (f.scope === "dashboard" || sec.scope === "dashboard")) out.add(f.key);
    });
  });
  return [...out];
};

const FINGERPRINT_KEY = "hemma_template_fingerprint";
const LAST_DASH_KEY = "hemma_panel_last_dashboard";
const NOT_HEMMA_KEY = "hemma_panel_not_hemma_v1";

const hashStr = (str) => {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return (h >>> 0).toString(36);
};

const fingerprintOf = (templates) => {
  const out = {};
  Object.keys(templates || {}).forEach((k) => { out[k] = hashStr(stable(templates[k])); });
  return out;
};

function energySubsAuto(rooms) {
  const home = (rooms || [])[0];
  const V = home && home.variables;
  if (!V || V.show_energy === false || V.energy_subs_auto === false) return false;
  return !(rooms || []).slice(1).some((r) => r && r.variables && r.variables.energy_cost_month);
}

function deriveEnergyRooms(rooms) {
  const list = rooms || [];
  const home = list[0];
  if (!home || !home.variables) return 0;
  const V = home.variables;
  if (V.show_energy === false) return 0;

  if (V.energy_subs_auto === false) return 0;
  if (V.energy_subs_auto === undefined) {
    for (let i = 1; i <= 6; i++) if (V["energy_entity_" + i]) return 0;
  }

  for (let i = 1; i <= 6; i++) {
    ["energy_entity_", "energy_label_", "energy_unit_", "energy_popup_name_",
     "energy_popup_power_", "energy_popup_today_", "energy_popup_month_",
     "energy_popup_cost_today_", "energy_popup_cost_month_"]
      .forEach((k) => { delete V[k + i]; });
  }

  const others = list.slice(1)
    .filter((r) => r && r.variables && r.variables.energy_cost_month);
  V.energy_subs_auto = true;
  let n = 0;
  others.slice(0, 6).forEach((r) => {
    const RV = r.variables;
    n += 1;
    V["energy_entity_" + n] = RV.energy_cost_month;
    V["energy_label_" + n] = r.name || r.path;
    V["energy_unit_" + n] = "cost";
    V["energy_popup_name_" + n] = r.name || r.path;
    if (RV.energy_power_entity) V["energy_popup_power_" + n] = RV.energy_power_entity;
    if (RV.energy_usage_today) V["energy_popup_today_" + n] = RV.energy_usage_today;
    if (RV.energy_usage_month) V["energy_popup_month_" + n] = RV.energy_usage_month;
    if (RV.energy_cost_today) V["energy_popup_cost_today_" + n] = RV.energy_cost_today;
    if (RV.energy_cost_month) V["energy_popup_cost_month_" + n] = RV.energy_cost_month;
  });
  return n;
}

const SCENE_KEYS = ["scenes", "scene_exclude", "scene_order", "scene_colors"];
const SCENE_LIST_KEYS = SCENE_KEYS.slice(0, 3);

function eachObject(o, fn) {
  if (Array.isArray(o)) o.forEach((x) => eachObject(x, fn));
  else if (o && typeof o === "object") {
    fn(o);
    Object.keys(o).forEach((k) => eachObject(o[k], fn));
  }
}

function scenePrefValue(key, v) {
  if (key === "scene_colors") {
    const map = Array.isArray(v) ? Object.assign({}, ...v.filter((x) => x && typeof x === "object")) : v;
    return map && typeof map === "object" && Object.keys(map).length ? clone(map) : null;
  }
  return Array.isArray(v) && v.length ? v.slice() : null;
}

function scenePrefsIn(root) {
  const out = {};
  const take = (holder) => {
    if (!holder) return;
    SCENE_KEYS.forEach((k) => {
      if (out[k] === undefined) {
        const val = scenePrefValue(k, holder[k]);
        if (val) out[k] = val;
      }
    });
  };
  const rows = [], cards = [];
  eachObject(root, (o) => {
    if (o.template === "hemma_scene_row" && o.variables) rows.push(o.variables);
    else if (o.type === "custom:hemma-nav" || o.type === FILTER_OVERLAY) cards.push(o);
  });
  rows.forEach(take);
  cards.forEach(take);
  const t = root && (root.button_card_templates || root.templates);
  take(t && t.hemma_scene_row && t.hemma_scene_row.variables);
  return out;
}

function seedScenePrefs(rooms, sources) {
  const list = (rooms || []).filter((r) => r && r.variables);
  if (!list.length) return 0;
  const found = {};
  SCENE_KEYS.forEach((k) => {
    if (k === "scene_colors") {
      const merged = {};
      list.slice().reverse().forEach((r) => Object.assign(merged, scenePrefValue(k, r.variables[k]) || {}));
      if (Object.keys(merged).length) found[k] = merged;
      return;
    }
    const at = list.find((r) => scenePrefValue(k, r.variables[k]));
    if (at) found[k] = scenePrefValue(k, at.variables[k]);
  });
  if (!Object.keys(found).length) {
    (sources || []).forEach((src) => {
      const got = scenePrefsIn(src);
      Object.keys(got).forEach((k) => { if (found[k] === undefined) found[k] = got[k]; });
    });
  }
  let n = 0;
  list.forEach((r) => {
    SCENE_KEYS.forEach((k) => {
      const want = found[k];
      if (stable(want === undefined ? null : want) === stable(scenePrefValue(k, r.variables[k]))) return;
      if (want === undefined) delete r.variables[k];
      else r.variables[k] = clone(want);
      n++;
    });
  });
  return n;
}

function applyMotion(cfg, rooms) {
  if (!cfg) return;
  const byName = {};
  (rooms || []).forEach((r) => {
    if (r && r.name) byName[r.name] = (r.variables || {}).motion_entity;
  });
  eachObject(cfg, (o) => {
    if (!o || o.template !== MOBILE_HEADER || !o.name) return;
    const m = byName[o.name];
    if (m) {
      o.variables = o.variables || {};
      o.variables.motion_entity = m;
    } else if (o.variables) {
      delete o.variables.motion_entity;
    }
  });
}

function applyScenePick(cfg, rooms) {
  if (!cfg) return;
  const src = ((rooms || [])[0] || {}).variables || {};
  const val = (k) => scenePrefValue(k, src[k]);
  if (cfg.button_card_templates) {
    cfg.button_card_templates = clone(cfg.button_card_templates);
    const row = cfg.button_card_templates.hemma_scene_row;
    if (row && row.variables) {
      SCENE_LIST_KEYS.forEach((k) => { row.variables[k] = val(k); });
      row.variables.scene_colors = val("scene_colors") || {};
    }
  }
  eachObject(cfg, (o) => {
    const nav = o.type === "custom:hemma-nav";
    if (nav || (o.type === FILTER_OVERLAY && o.room)) {
      (nav ? SCENE_KEYS : SCENE_LIST_KEYS).forEach((k) => {
        const x = val(k);
        if (x) o[k] = x; else delete o[k];
      });
    } else if (o.template === "hemma_scene_row" && o.variables) {
      SCENE_KEYS.forEach((k) => delete o.variables[k]);
      if (!Object.keys(o.variables).length) delete o.variables;
    }
  });
}

function applyKiosk(cfg, rooms) {
  const v = (((rooms || [])[0] || {}).variables) || {};
  const hide = v.hemma_hide_header !== false;
  const prev = cfg.kiosk_mode || {};
  const users = (prev.user_settings || []).map((u) => omit(u, ["hide_header"]));
  const out = {
    ...prev,
    hide_header: hide,
    mobile_settings: { ...(prev.mobile_settings || {}), hide_header: hide },
  };
  Object.keys(KIOSK_DIALOG).forEach((k) => {
    const [key, def] = KIOSK_DIALOG[k];
    if (v[k] === undefined && prev[key] === undefined) return;
    out[key] = v[k] === undefined ? def : v[k] !== false;
  });
  if (users.length) out.user_settings = users;
  cfg.kiosk_mode = out;
}

function seedKiosk(rooms, cfg) {
  const km = (cfg || {}).kiosk_mode;
  const list = rooms || [];
  if (!km || !list.length) return 0;
  let n = 0;
  const seed = (rv, on, def) => {
    if (on === def) return;
    list.forEach((r) => { if (r.variables[rv] === undefined) { r.variables[rv] = on; n++; } });
  };
  if (km.hide_header !== undefined) seed("hemma_hide_header", !!km.hide_header, true);
  Object.keys(KIOSK_DIALOG).forEach((rv) => {
    const [key, def] = KIOSK_DIALOG[rv];
    if (km[key] !== undefined) seed(rv, !!km[key], def);
  });
  return n;
}

function withoutRoutes(o) {
  if (Array.isArray(o)) return o.map(withoutRoutes);
  if (o && typeof o === "object") {
    const out = {};
    Object.keys(o).forEach((k) => { if (k !== "routes") out[k] = withoutRoutes(o[k]); });
    return out;
  }
  return o;
}

function upgradeNavExtra(r) {
  const legacy = r && (r.popup !== undefined
    || (r.tap_action && r.tap_action.action === "open-popup"));
  if (!legacy) return r;
  const out = { ...r, menu: r.menu || "scenes" };
  delete out.popup;
  delete out.tap_action;
  return out;
}

function refreshTemplates(current, bundleTemplates, priorPrints) {
  const next = { ...(current || {}) };
  const seen = priorPrints || {};
  const prints = {};
  const adopted = [];
  const mine = [];
  const redeclared = [];
  const unknown = [];
  let updated = 0, added = 0, kept = 0;

  Object.keys(bundleTemplates).forEach((k) => {
    const have = next[k];
    const ship = bundleTemplates[k];
    const shipPrint = hashStr(stable(ship));
    const take = () => { next[k] = ship; prints[k] = shipPrint; adopted.push(k); };
    if (have === undefined) { added += 1; take(); return; }
    const havePrint = hashStr(stable(have));
    if (havePrint === shipPrint) { prints[k] = shipPrint; adopted.push(k); return; }
    const last = seen[k];
    if (last === havePrint) { updated += 1; take(); return; }
    // No record of it either way, so an old Hemma and a hand edit look the
    // same. Set it back, but name it rather than go quiet.
    if (last === undefined) { unknown.push(k); take(); return; }
    // Hemma is not what wrote this one, so it is the user's to keep. Its
    // variables: block still declares the fields Studio builds its form from,
    // so ship's declarations fill any the fork dropped without touching a value.
    const theirs = (have && have.variables) || null;
    const shipVars = (ship && ship.variables) || null;
    if (shipVars && theirs && stable(theirs) !== stable({ ...shipVars, ...theirs })) {
      next[k] = { ...have, variables: { ...shipVars, ...theirs } };
      redeclared.push(k);
    }
    prints[k] = last;
    kept += 1;
    mine.push(k);
  });

  const removed = [];
  const foreign = [];
  const orphan = [];
  Object.keys(next).forEach((k) => {
    if (bundleTemplates[k] !== undefined) return;
    const ours = k.indexOf("hemma_") === 0;
    if (ours && seen[k] !== undefined && seen[k] === hashStr(stable(next[k]))) {
      delete next[k];
      removed.push(k);
      return;
    }
    (ours ? orphan : foreign).push(k);
  });

  return { templates: next, prints, adopted, mine, redeclared, unknown, updated,
    added, kept, removed, foreign, orphan };
}

