const warmPhoto = (url) => {
  if (!url || PHOTO_CACHE.has(url)) return;
  const img = new Image();
  img.decoding = "async";
  PHOTO_CACHE.set(url, img);
  img.src = url;
  if (img.decode) img.decode().catch(() => {});
};

const iconUrl = (name) => {
  const n = String(name || "").trim();
  const k = !n || n === ICON_DEFAULT ? "default" : n;
  return ICON_DATA[k] || ICON_DATA.default;
};

function retargetRoutes(root, urlPath, rooms, extras) {
  const out = clone(root);
  let rewritten = 0;

  (function walk(node) {
    if (!node || typeof node !== "object") return;
    if (Array.isArray(node)) { node.forEach(walk); return; }
    if (Array.isArray(node.routes)) {
      const keep = extras === undefined ? node.routes.filter((r) => !r.url) : extras;
      node.routes = rooms
        .map((r) => {
          const route = { url: `/${urlPath}/${r.path}`, label: r.name, icon: roomIcon(r.name) };
          const m = (r.variables || {}).motion_entity;
          // The global helper is a mute switch: absent means nothing to mute.
          if (m) route.badge = { show: "[[[ const b = states['input_boolean.hemma_motion_badges'];"
            + " if (b && b.state !== 'on') return false;"
            + " const s = states['" + m + "'];"
            + " return !!s && s.state === 'on'; ]]]" };
          return route;
        })
        .concat(clone(keep));
      rewritten += 1;
    }
    Object.keys(node).forEach((k) => walk(node[k]));
  })(out);

  return { config: out, rewritten };
}


