const tileFieldsFor = (type, phone) => (type && type.fields ? type.fields : [])
  .concat(phone === true || phone === "mobile" ? MOBILE_TILE_FIELDS : []);

const tileLabel = (tile) => {
  const t = tile.template;
  return Array.isArray(t) ? t.join(" + ") : String(t || tile.type || "card");
};

// Tile types the user brought, derived from the templates Hemma does not own.
// Nothing new is stored: a template that is not hemma_'s is a tile type.
const USER_TILE_TYPES = [];


const ENTITY_ID = /^[a-z_]+\.[a-z0-9_]+$/;


const prettyKey = (k) => String(k).replace(/_/g, " ").replace(/^./, (c) => c.toUpperCase());

function userTypeFields(tpl) {
  const declared = (tpl && tpl.variables) || {};
  return Object.keys(declared).filter((k) => !TILE_OWN_KEYS.has(k)).map((k) => {
    const def = declared[k];
    if (typeof def === "boolean") {
      return { key: k, label: prettyKey(k), type: "bool", boolDefault: def };
    }
    if (typeof def === "string" && ENTITY_ID.test(def)) {
      return { key: k, label: prettyKey(k), domains: [def.split(".")[0]] };
    }
    return { key: k, label: prettyKey(k), type: "text" };
  });
}

// A template earns a place in the picker by evidence, not by not being Hemma's.
// Either a tile in some room already uses it, or it says so itself. Popup and
// base templates say neither, so they stay out.
function syncUserTileTypes(templates, rooms, alsoInUse, prints) {
  USER_TILE_TYPES.length = 0;
  const inUse = new Set(alsoInUse || []);
  const ours = prints || {};
  (rooms || []).forEach((r) => (r.tiles || []).forEach((t) => {
    if (t && typeof t.template === "string") inUse.add(t.template);
  }));
  Object.keys(templates || {}).forEach((name) => {
    if (name.indexOf("hemma_") === 0) return;
    // The fingerprint, not the name, is what says who owns a template. One that
    // arrived in Hemma's bundle is Hemma's however it happens to be spelled,
    // and calling it "yours" would promise an edit that the next save reverts.
    if (ours[name] !== undefined) return;
    const tpl = templates[name] || {};
    const optedIn = !!(tpl.variables && tpl.variables.hemma_tile);
    if (!inUse.has(name) && !optedIn) return;
    USER_TILE_TYPES.push({
      id: "user:" + name,
      label: prettyKey(name),
      template: name,
      user: true,
      domains: ACTION_DOMAINS,
      entityPlaceholder: _sx("The entity this tile shows"),
      fields: userTypeFields(tpl),
    });
  });
  return USER_TILE_TYPES.length;
}

const findType = (pool, t) => {
  if (typeof t === "string") return pool.find((x) => x.template === t) || null;
  if (Array.isArray(t)) {
    return pool.find(
      (x) => Array.isArray(x.template) && stable(x.template) === stable(t)
    ) || null;
  }
  return null;
};

// Built-ins only. Pair sync asks "is this Hemma's shape", and a user's tile is
// deliberately not, so this must not widen when their types are registered.
const tileTypeOf = (tile) => findType(TILE_TYPES, tile.template);

// Everything the form can edit, the user's types included.
const tileTypeAny = (tile) =>
  tileTypeOf(tile) || findType(USER_TILE_TYPES, tile.template);

function newTile(type) {
  return { type: "custom:button-card", template: type.template, entity: "", name: type.user ? type.label : _sx(type.label) };
}

// Candidate for hemma-panel.js: enough YAML to read a card config off the
// clipboard. Anything it cannot read, it refuses by line rather than guessing.

function stripComment(line) {
  let q = null;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (q) { if (c === q) q = null; continue; }
    if (c === '"' || c === "'") { q = c; continue; }
    if (c === "#" && (i === 0 || /\s/.test(line[i - 1]))) return line.slice(0, i);
  }
  return line;
}

// "content: |" is how half the cards in the wild carry their text, and the
// parser below is indent driven, so the block is folded into one quoted scalar
// before it ever sees it. Quoting also protects a markdown "## heading" from
// the comment stripper.
function foldBlockScalars(src) {
  const lines = String(src).replace(/\r\n?/g, "\n").split("\n");
  const out = [];
  const quote = (s) => '"' + s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')
    .replace(/\n/g, "\\n") + '"';
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].replace(/\t/g, "  ");
    const m = line.match(/^(\s*)([^:#]+):\s*([|>])([+-]?)\d*\s*$/);
    if (!m) { out.push(line); continue; }
    const pad = m[1], key = m[2], style = m[3], chomp = m[4];
    const body = [];
    let j = i + 1;
    for (; j < lines.length; j++) {
      const l = lines[j].replace(/\t/g, "  ");
      if (!l.trim()) { body.push(""); continue; }
      if (l.length - l.replace(/^ +/, "").length <= pad.length) break;
      body.push(l);
    }
    while (body.length && !body[body.length - 1].trim()) body.pop();
    if (!body.length) { out.push(pad + key + ": \"\""); i = j - 1; continue; }
    const strip = Math.min.apply(null, body.filter((b) => b.trim())
      .map((b) => b.length - b.replace(/^ +/, "").length));
    let text = body.map((b) => b.slice(strip)).join("\n");
    if (style === ">") {
      text = text.split(/\n{2,}/).map((p) => p.replace(/\n/g, " ")).join("\n\n");
    }
    if (chomp !== "-") text += "\n";
    out.push(pad + key + ": " + quote(text));
    i = j - 1;
  }
  return out.join("\n");
}

function yamlLines(src) {
  const out = [];
  String(src).replace(/\r\n?/g, "\n").split("\n").forEach((raw) => {
    const body = stripComment(raw.replace(/\t/g, "  "));
    if (!body.trim()) return;
    out.push({ indent: body.length - body.replace(/^ +/, "").length, text: body.trim() });
  });
  return out;
}

function yamlScalar(t) {
  if (t === "" || t === "~" || t === "null") return null;
  if (t === "true") return true;
  if (t === "false") return false;
  if (/^-?\d+$/.test(t)) return parseInt(t, 10);
  if (/^-?\d*\.\d+$/.test(t)) return parseFloat(t);
  const q = t[0];
  if ((q === '"' || q === "'") && t.slice(-1) === q && t.length > 1) {
    const body = t.slice(1, -1);
    return q === '"'
      ? body.replace(/\\n/g, "\n").replace(/\\"/g, '"').replace(/\\\\/g, "\\")
      : body.replace(/''/g, "'");
  }
  if (q === "{" || q === "[") {
    try { return JSON.parse(t); } catch (e) {
      throw new Error(_sx("Could not read this value: {value}", { value: t }));
    }
  }
  return t;
}

function yamlNode(lines, i, indent) {
  return lines[i].text[0] === "-"
    ? yamlList(lines, i, indent) : yamlMap(lines, i, indent);
}

function yamlMap(lines, i, indent) {
  const out = {};
  while (i < lines.length && lines[i].indent >= indent) {
    if (lines[i].indent > indent) throw new Error(_sx("Unexpected indent at: {line}", { line: lines[i].text }));
    const m = lines[i].text.match(/^([^:]+):(?:\s+(.*))?$/);
    if (!m) throw new Error(_sx("Expected \"key: value\" at: {line}", { line: lines[i].text }));
    const key = m[1].trim().replace(/^["']|["']$/g, "");
    const rest = (m[2] || "").trim();
    if (rest) { out[key] = yamlScalar(rest); i++; continue; }
    const nxt = lines[i + 1];
    if (nxt && (nxt.indent > indent
      || (nxt.indent === indent && nxt.text[0] === "-"))) {
      const r = yamlNode(lines, i + 1, nxt.indent);
      out[key] = r[0]; i = r[1]; continue;
    }
    out[key] = null; i++;
  }
  return [out, i];
}

function yamlList(lines, i, indent) {
  const out = [];
  while (i < lines.length && lines[i].indent === indent && lines[i].text[0] === "-") {
    const rest = lines[i].text.slice(1).trim();
    if (!rest) {
      const nxt = lines[i + 1];
      if (nxt && nxt.indent > indent) {
        const r = yamlNode(lines, i + 1, nxt.indent);
        out.push(r[0]); i = r[1];
      } else { out.push(null); i++; }
      continue;
    }
    if (/^[^:]+:(\s|$)/.test(rest)) {
      // "- key: value" opens a map; its siblings sit under the dash.
      const inner = [{ indent: 0, text: rest }];
      const off = lines[i].indent + 2;
      let j = i + 1;
      while (j < lines.length && lines[j].indent >= off) {
        inner.push({ indent: lines[j].indent - off, text: lines[j].text });
        j++;
      }
      out.push(yamlMap(inner, 0, 0)[0]);
      i = j; continue;
    }
    out.push(yamlScalar(rest)); i++;
  }
  return [out, i];
}

// One paste box, two things worth pasting: a card, or a template that becomes a
// reusable tile type. Telling them apart is what lets people skip the raw
// config editor entirely.
function parsePasted(text) {
  const src = String(text || "").trim();
  if (!src) throw new Error(_sx("Paste a card or a template first."));
  let doc;
  if (src[0] === "{" || src[0] === "[") {
    try { doc = JSON.parse(src); } catch (e) {
      throw new Error(_sx("That looks like JSON but does not parse: {error}", { error: e.message }));
    }
  } else {
    const lines = yamlLines(foldBlockScalars(src));
    if (!lines.length) throw new Error(_sx("Paste a card or a template first."));
    if (lines[0].indent) throw new Error(_sx("The first line should not be indented."));
    doc = yamlNode(lines, 0, 0)[0];
  }
  if (!doc || typeof doc !== "object" || Array.isArray(doc)) {
    throw new Error(_sx("A card is a set of keys, starting with \"type:\"."));
  }
  if (doc.type) return { kind: "card", card: doc };

  const keys = Object.keys(doc);
  const body = keys.length === 1 ? doc[keys[0]] : null;
  if (body && typeof body === "object" && !Array.isArray(body)) {
    if (keys[0].indexOf("hemma_") === 0) {
      throw new Error(_sx("Names beginning with \"hemma_\" belong to Hemma and are "
        + "replaced when it updates. Give yours a different name."));
    }
    return { kind: "template", name: keys[0], template: body };
  }
  throw new Error(_sx("A card needs a \"type:\" line."));
}

const parseCardText = (text) => {
  const got = parsePasted(text);
  if (got.kind !== "card") throw new Error(_sx("That is a template, not a card."));
  return got.card;
};

// The inverse of the parser above, held to the same grammar: whatever this
// writes, parsePasted has to read back.
function yamlScalarText(v) {
  if (v === null || v === undefined) return "null";
  if (typeof v === "boolean" || typeof v === "number") return String(v);
  if (typeof v === "object") return JSON.stringify(v);
  const s = String(v);
  // " #" is a comment to the parser and ": " opens a map, so neither stays bare.
  const bare = s !== ""
    && !/^[-?:,[\]{}#&*!|>'"%@`]/.test(s)
    && !/:\s|:$|\s#|^\s|\s$|\n/.test(s)
    && !/^(true|false|null|~|-?\d+(\.\d+)?)$/.test(s);
  return bare ? s
    : '"' + s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n") + '"';
}

function yamlEmit(obj, indent, out) {
  const pad = " ".repeat(indent);
  Object.keys(obj).forEach((k) => {
    const v = obj[k];
    if (v && typeof v === "object" && !Array.isArray(v)) {
      if (!Object.keys(v).length) { out.push(pad + k + ": {}"); return; }
      out.push(pad + k + ":");
      yamlEmit(v, indent + 2, out);
      return;
    }
    if (Array.isArray(v)) {
      if (!v.length) { out.push(pad + k + ": []"); return; }
      out.push(pad + k + ":");
      v.forEach((item) => {
        if (item && typeof item === "object" && !Array.isArray(item)) {
          const inner = [];
          yamlEmit(item, 0, inner);
          inner.forEach((line, n) => out.push(pad + "  " + (n ? "  " : "- ") + line));
          return;
        }
        out.push(pad + "  - " + yamlScalarText(item));
      });
      return;
    }
    if (typeof v === "string" && v.indexOf("\n") >= 0) {
      // Written back the way it was pasted, so Edit stays readable.
      const keep = /\n$/.test(v);
      out.push(pad + k + ": |" + (keep ? "" : "-"));
      v.replace(/\n$/, "").split("\n").forEach((line) => {
        out.push(line ? pad + "  " + line : "");
      });
      return;
    }
    out.push(pad + k + ": " + yamlScalarText(v));
  });
}

const cardToText = (card) => {
  const out = [];
  yamlEmit(card, 0, out);
  return out.join("\n") + "\n";
};


const ENTITY_ACTIVE_STATES = ["on", "open", "opening", "unlocked", "unlocking",
  "playing", "cleaning", "returning", "cool", "heat", "washing", "rinsing",
  "spinning", "drying", "running", "active", "problem"];

const numOf = (states, id) => {
  const raw = id && (states[id] || {}).state;
  if (!raw || raw === "unavailable" || raw === "unknown") return null;
  const n = parseFloat(raw);
  return Number.isNaN(n) ? null : n;
};

// hemma_light: one row per physical light, groups of groups flattened.
const lightUnits = (states, eid, seen) => {
  const memsOf = (id) => {
    const m = ((states[id] || {}).attributes || {}).entity_id;
    return Array.isArray(m) ? m.filter((x) => typeof x === "string" && x.startsWith("light.")) : [];
  };
  if (!eid || seen.has(eid)) return [];
  const mems = memsOf(eid);
  if (!mems.length || !mems.some((m) => memsOf(m).length)) return [eid];
  seen.add(eid);
  return mems.flatMap((m) => lightUnits(states, m, seen));
};
const lightWord = (states, eid) => {
  const all = [...new Set(lightUnits(states, eid, new Set()))];
  const lit = all.filter((e) => (states[e] || {}).state === "on").length;
  return lit === 0 ? _studioT("lights.all_off", "All Off") : lit === all.length ? _studioT("lights.all_on", "All On") : _studioT("lights.n_on", "{n} On", { n: lit });
};

const batteryPack = (V, states) => {
  const list = V.batteries || V.entity_filter;
  const pool = Array.isArray(list)
    ? list.map((id) => states[id]).filter(Boolean)
    : Object.values(states);
  const pack = pool.filter((e) => {
    if (e.state === "unavailable" || e.state === "unknown") return false;
    if (Number.isNaN(parseFloat(e.state))) return false;
    return e.attributes && e.attributes.device_class === "battery";
  });
  return { count: pack.length, low: pack.some((e) => parseFloat(e.state) <= 20) };
};

// hemma_plex_recently_added counts titles added in the last three days.
const plexAdded = (states) => {
  const rows = (id) => {
    const d = ((states[id] || {}).attributes || {}).data;
    return Array.isArray(d) ? d.slice(1).filter((i) => i && i.title) : [];
  };
  const cutoff = Date.now() - 3 * 24 * 60 * 60 * 1000;
  return rows("sensor.recently_added_movies").concat(rows("sensor.recently_added_tv"))
    .filter((i) => i.airdate && new Date(i.airdate).getTime() >= cutoff).length;
};

const networkWan = (V, ent, states) => {
  const dl = numOf(states, V.entity_download || (ent && ent.entity_id));
  const ul = numOf(states, V.entity_upload || V.upload_sensor);
  const vals = [dl, ul].filter((v) => v != null);
  return { dl: dl, ul: ul, max: vals.length ? Math.max(...vals) : 0 };
};
const networkWord = (V, ent, states) => {
  const w = networkWan(V, ent, states);
  if (w.max < Number(V.idle_threshold ?? 1)) return _studioT("network.idle", "Idle");
  const tier = w.max < Number(V.light_threshold ?? 10) ? _studioT("network.light", "Light")
    : w.max < Number(V.heavy_threshold ?? 50) ? _studioT("network.active", "Active") : _studioT("network.heavy", "Heavy");
  const dir = (w.dl == null || (w.ul != null && w.ul > w.dl)) ? _studioT("network.upload", "Upload") : _studioT("network.download", "Download");
  return _studioT("network.activity", "{tier} {dir}", { tier, dir });
};

// hemma_energy prints the same tier word its popup and sub-badges do.
const energyWord = (V, ent, states) => {
  const w = numOf(states, V.entity_power || (ent && ent.entity_id));
  if (w == null) return _studioL("state.default.unavailable", "Unavailable");
  if (w >= Number(V.extreme_threshold ?? 3000)) return _studioT("energy.extreme_usage", "Extreme Usage");
  if (w >= Number(V.heavy_threshold ?? 1000)) return _studioT("energy.heavy_usage", "Heavy Usage");
  if (w >= Number(V.normal_threshold ?? 200)) return _studioT("energy.normal", "Normal");
  return _studioT("energy.idle", "Idle");
};

const plantActive = (ent, V, states) => {
  const state = String(ent.state || "").toLowerCase();
  if (state === "problem") return true;
  if (state === "ok") return false;
  const attrs = ent.attributes || {};
  const sensors = Array.isArray(V.sensors) ? V.sensors.filter(Boolean) : [];
  // Battery is not graded - hemma_plant's own getSensorType leaves it out.
  const graded = (id) => { const t = plantSlotOf(id); return t === "battery" ? null : t; };
  if (sensors.some((id) => {
    if (numOf(states, id) == null) return false;
    const t = graded(id);
    if (!t) return false;
    const v = attrs[t + "_status"];
    return !!v && v !== "ok" && v !== "null";
  })) return true;
  const threshold = Number(V.low_threshold ?? 30);
  const val = parseFloat(ent.state);
  if (Number.isFinite(val)) return val <= threshold;
  const attr = parseFloat(attrs.moisture);
  return Number.isFinite(attr) && attr <= threshold;
};

const plantWord = (ent, V, states) => {
  const state = String(ent.state || "");
  if (!state || state === "unavailable") return "— %";
  if (state === "ok") return _studioT("state.healthy", "Healthy");
  const attrs = ent.attributes || {};
  const sensors = Array.isArray(V.sensors) ? V.sensors.filter(Boolean) : [];
  const graded = (id) => { const t = plantSlotOf(id); return t === "battery" ? null : t; };
  if (sensors.length && state === "problem") {
    const scorable = sensors.filter((id) => {
      const t = graded(id);
      return t && Object.prototype.hasOwnProperty.call(attrs, t + "_status");
    });
    const scored = scorable.filter((id) => numOf(states, id) != null);
    if (scorable.length && !scored.length) return _studioL("state.default.unavailable", "Unavailable");
    if (scored.length) {
      const bad = scored.filter((id) => {
        const v = attrs[graded(id) + "_status"];
        return v && v !== "ok" && v !== "null";
      }).length;
      const ratio = (scored.length - bad) / scored.length;
      if (ratio >= 1) return _studioT("state.healthy", "Healthy");
      if (ratio >= 0.8) return _studioT("plant.needs_care", "Needs care");
      if (ratio >= 0.6) return _studioT("plant.struggling", "Struggling");
      if (ratio >= 0.4) return _studioT("plant.poor", "Poor");
      return _studioT("plant.critical", "Critical");
    }
  }
  if (state === "problem") return _studioT("state.needs_attention", "Needs Attention");
  const val = parseFloat(state);
  if (!Number.isNaN(val)) return Math.round(val) + " %";
  const attr = parseFloat(attrs.moisture);
  if (!Number.isNaN(attr)) return Math.round(attr) + " %";
  return "— %";
};

const mediaWord = (ent) => {
  const cap = (x) => (x ? x.charAt(0).toUpperCase() + x.slice(1).replace(/_/g, " ") : "");
  const state = String(ent.state || "").toLowerCase();
  if (state !== "playing") return state ? _studioL("component.media_player.entity_component._.state." + state, cap(state)) : _studioL("component.media_player.entity_component._.state.off", "Off");
  const a = ent.attributes || {};
  const id = ent.entity_id || "";
  const type = String(a.media_content_type || "").toLowerCase();
  const title = String(a.media_title || a.title || "").trim();
  const artist = String(a.media_artist || a.artist || a.media_album_artist || "").trim();
  const app = String(a.app_name || "").trim();
  const source = String(a.source || a.media_channel || "").trim();
  const isMusic = type === "music" || id.includes("spotify")
    || (!!artist && !["movie", "video", "tvshow"].includes(type));
  if (isMusic) return (artist && title) ? artist + " - " + title : (title || artist || app || source || cap(state));
  return title || app || source || _studioL("component.media_player.entity_component._.state." + state, cap(state));
};

const cameraAlert = (hass, states, cams, windowMinutes) => {
  const reg = (hass && hass.entities) || {};
  const devs = {};
  cams.forEach((id) => {
    const d = reg[id] && reg[id].device_id;
    if (d) devs[d] = true;
  });
  const span = (Number(windowMinutes) > 0 ? Number(windowMinutes) : 5) * 60000;
  const now = Date.now();
  let ding = false, motion = false;
  Object.keys(reg).forEach((id) => {
    if (id.indexOf("event.") !== 0) return;
    if (!devs[reg[id].device_id]) return;
    const t = Date.parse(states[id] && states[id].state);
    if (!isFinite(t) || now - t > span) return;
    if (/ding|doorbell|button/.test(id)) ding = true;
    else if (/motion/.test(id)) motion = true;
  });
  return ding ? _studioT("cameras.doorbell", "Doorbell") : motion ? _studioT("cameras.motion_detected", "Motion Detected") : "";
};

const cameraWord = (V, states, hass) => {
  const cams = (Array.isArray(V.cameras) ? V.cameras : []).filter(Boolean);
  if (!cams.length) return _studioT("cameras.none", "No Cameras");
  const DEAD = ["unavailable", "unknown", ""];
  const dead = cams.filter((id) =>
    DEAD.includes(String((states[id] || {}).state || "").toLowerCase())).length;
  if (dead === cams.length) return cams.length === 1 ? _studioT("cameras.offline", "Offline") : _studioT("cameras.all_offline", "All Offline");
  if (dead > 0) return _studioT("cameras.n_offline", "{n} Offline", { n: dead });
  return cameraAlert(hass, states, cams, V.alert_window_minutes) || _studioT("cameras.no_alerts", "No Alerts");
};

const tileShowWhen = (type, V) =>
  String((V || {}).show_when || (type && type.whenDefault) || "always");

const tileOnSurface = (t, phone) => {
  const s = ((t || {}).variables || {}).surfaces;
  if (s === "phone") return !!phone;
  if (s === "desktop") return !phone;
  return true;
};

const tileHidesNow = (type, kind, ent, V, states) =>
  tileShowWhen(type, V) === "active" && !tileActive(kind, ent, V || {}, states);

const tileActive = (kind, ent, V, states) => {
  if (!ent) return false;
  const state = String(ent.state || "").toLowerCase();
  switch (kind) {
    // Templates that override hemma_entity's state: block with their own rule.
    case "plant": return plantActive(ent, V, states);
    case "energy_tile": {
      const w = numOf(states, ent.entity_id);
      return w != null && w >= Number(V.high_threshold ?? 500);
    }
    case "network":
      return networkWan(V, ent, states).max >= Number(V.light_threshold ?? 10);
    case "updates": {
      const n = Number(ent.state);
      return Number.isFinite(n) && n > 0;
    }
    case "game": return gameActivity(ent).active;
    case "plex": return plexAdded(states) > 0;
    case "battery": return batteryPack(V, states).low;
    default: break;
  }
  const extra = Array.isArray(V.active_states)
    ? V.active_states.map((x) => String(x).toLowerCase()) : [];
  return ENTITY_ACTIVE_STATES.includes(state) || extra.includes(state);
};

const GAME_NOT_A_TITLE = ["playing", "paused", "idle", "on", "off", "home", "away",
  "online", "offline", "standby", "unavailable", "unknown", "none", "null", ""];
const GAME_DEAD_STATES = ["offline", "off", "none", "unavailable", "unknown", ""];

const gameActivity = (ent) => {
  const a = (ent && ent.attributes) || {};
  const named = String(a.game == null ? "" : a.game).trim();
  const st = String((ent && ent.state) || "").trim();
  let game = "";
  if (named && ["none", "unknown", "unavailable"].indexOf(named.toLowerCase()) < 0) {
    game = named;
  } else if (GAME_NOT_A_TITLE.indexOf(st.toLowerCase()) < 0) {
    game = st;
  }
  const active = !!game && GAME_DEAD_STATES.indexOf(st.toLowerCase()) < 0;
  const art = [a.game_image_main, a.game_image_header, a.game_icon]
    .map((x) => String(x == null ? "" : x).trim())
    .find(Boolean) || "";
  return { game: game, active: active, art: active ? art : "" };
};

const mediaArtUrl = (ent, states) => {
  if (!ent) return "";
  if (String(ent.state || "").toLowerCase() !== "playing") return "";
  const a = ent.attributes || {};
  const id = ent.entity_id || "";
  const type = String(a.media_content_type || "").toLowerCase();
  const app = String(a.app_name || "").trim();
  const title = String(a.media_title || a.title || "").trim();
  const source = String(a.source || a.media_channel || "").trim();
  const isSonos = id.includes("sonos")
    || String(a.friendly_name || "").toLowerCase().includes("sonos");
  const bareInputs = ["tv", "hdmi", "arc", "hdmi arc", "optical", "line-in", "line in"];
  let looksLikeBareInput = false;
  if (isSonos && title) {
    const t = title.toLowerCase();
    looksLikeBareInput = bareInputs.indexOf(t) !== -1
      || (!!source && t === source.toLowerCase());
  }
  const isYouTube = app.toLowerCase().includes("youtube");
  const yt = states && states["sensor.youtube_watching"];
  const pic = isYouTube
    ? ((yt && yt.attributes && yt.attributes.thumbnail) || a.entity_picture || "")
    : (a.entity_picture || "");
  const hasRichMeta = !!(a.media_series_title || a.media_episode_title);
  const fromRichApp =
    /youtube|plex|netflix|hulu|disney|max|prime|spotify|apple tv|apple music|paramount|peacock/i
      .test(app);
  const rich = hasRichMeta
    || ["music", "movie", "video", "tvshow", "game"].indexOf(type) !== -1
    || fromRichApp;
  if (!pic || looksLikeBareInput || !rich) return "";
  return pic.startsWith("/") ? window.location.origin + pic : pic;
};

// ── Now Playing: _hemmaNPSources, ported ─────────────────────────────────────
const npAbs = (u) => {
  if (!u) return "";
  const raw = String(u);
  const full = raw.startsWith("/") ? (window.location.origin + raw) : raw;
  try {
    const p = new URL(full, window.location.origin);
    // authSig signs the exact param list, so editing the query 401s it.
    if (p.searchParams.has("authSig")) return full;
    p.searchParams.delete("refresh");
    return p.toString();
  } catch (e) { return full; }
};

// hemma-core.js's list, verbatim. Anything else the state says is the game.
const PSN_NOT_A_TITLE = new Set([
  "playing", "paused", "idle", "on", "off", "home", "away", "online",
  "offline", "standby", "unavailable", "unknown", "none", "null", "",
]);

const npStarted = (s) => {
  const n = s && s.last_changed ? Date.parse(s.last_changed) : NaN;
  return Number.isFinite(n) ? n : 0;
};

const npPlexHidden = (V, user) => {
  const raw = String((V || {}).plex_hide_users || "");
  const u = String(user == null ? "" : user).trim().toLowerCase();
  if (!raw.trim() || !u) return false;
  return raw.split(",").map((x) => x.trim().toLowerCase())
    .filter(Boolean).indexOf(u) !== -1;
};

const npSource = (kind, id, states) => {
  const s = id && states[id];
  if (!s) return null;
  const a = s.attributes || {};
  const norm = (x) => String(x == null ? "" : x).trim();
  const low = (x) => norm(x).toLowerCase();
  const st = low(s.state);

  if (kind === "plex") {
    const full = norm(a.full_title || a.title);
    if (!full) return null;
    const tau = String(id).replace(/^(sensor\.)plex_stream_(\d+)$/,
      "$1plex_session_$2_tautulli");
    const pst = low((states[tau] || {}).state || s.state);
    if (pst !== "playing" && pst !== "buffering") return null;
    return {
      kind: "plex", playing: true, started: npStarted(s),
      art: npAbs(a.image_url || a.entity_picture_local || a.entity_picture
        || a.media_image_url),
      title: full, subtitle: "",
      source: _studioT("media.plex_user", "Plex · {user}", { user: norm(a.user) || _studioL("state.default.unknown", "Unknown") }),
      controls: { toggle: false, next: false, prev: false },
    };
  }

  if (kind === "psn") {
    if (["unavailable", "unknown", "off", "standby", "none", ""].includes(st)) return null;
    const attrTitle = norm(a.full_title || a.media_title || a.title);
    const stateIsTitle = !attrTitle && !PSN_NOT_A_TITLE.has(st);
    const title = attrTitle || (stateIsTitle ? norm(s.state) : "");
    if (!title) return null;
    const iid = String(id).replace(/^sensor\./, "image.");
    const im = states[iid];
    const iat = (im && im.attributes) || {};
    const sib = iat.entity_picture_local || iat.entity_picture
      || (im && iat.access_token ? "/api/image_proxy/" + iid + "?token=" + iat.access_token : "");
    return {
      kind: "activity", started: npStarted(s),
      playing: stateIsTitle ? true : st === "playing",
      art: npAbs(a.entity_picture_local || a.entity_picture || a.image_url
        || a.media_image_url || sib),
      title: title, subtitle: norm(a.user),
      source: norm(a.friendly_name) || norm(a.source) || "PlayStation",
      controls: { toggle: false, next: false, prev: false },
    };
  }

  const feats = Number(a.supported_features || 0);
  const controls = { toggle: !!(feats & 16385), next: !!(feats & 32),
    prev: !!(feats & 16) };
  const rawTitle = norm(a.media_title);
  let artist = norm(a.media_artist || a.artist || a.media_album_artist);
  const hasContent = !!(rawTitle || artist);
  if (st !== "playing" && st !== "buffering") {
    if (st !== "paused" || !hasContent
      || !(controls.toggle || controls.next || controls.prev)) return null;
  }

  let title = rawTitle;
  if (!artist && a.media_content_type === "tvshow") {
    const series = norm(a.media_series_title);
    const season = a.media_season ? "S" + String(a.media_season).padStart(2, "0") : "";
    const episode = a.media_episode ? "E" + String(a.media_episode).padStart(2, "0") : "";
    artist = [series, [season, episode].filter(Boolean).join("")]
      .filter(Boolean).join(" \u00b7 ");
  }
  if (!artist) {
    const parts = rawTitle.split(/\s+[-\u2013\u2014]\s+/);
    if (parts.length >= 3) {
      title = parts[parts.length - 1];
      artist = parts.slice(0, -1).join(" \u2013 ");
    }
  }
  let art = npAbs(a.entity_picture || a.media_image_url || a.media_album_cover_url
    || a.image_url);
  if (!art) {
    const app = low(a.app_name || a.source) + " " + low(a.app_id);
    if (app.includes("youtube")) art = npAbs("/local/hemma/icons/youtube.png");
  }
  return {
    kind: "player", playing: st === "playing" || st === "buffering",
    started: npStarted(s),
    art: art, title: title || norm(a.friendly_name) || _studioT("media.title", "Media"),
    subtitle: artist, source: norm(a.app_name || a.source || a.friendly_name),
    controls: controls,
    pos: Number(a.media_position), dur: Number(a.media_duration),
  };
};

// HA rotates an image entity's ?token= every 5 minutes and 403s the old one.
const npArtHold = {};
const npArtWarm = new Map();

// The cover's identity is in the query, never the path.
const npArtKey = (u, id) => {
  const t = String(u || "");
  const q = t.indexOf("?");
  if (q < 0) return t + "|" + id;
  const rest = t.slice(q + 1).split("&")
    .filter((p) => p.slice(0, 6) !== "token=" && p.slice(0, 8) !== "authSig=")
    .sort().join("&");
  return t.slice(0, q) + (rest ? "?" + rest : "") + "|" + id;
};

// An external cover (Plex art, Steam, Discord) has no param that rotates.
const npArtRotates = (u) => {
  try {
    const p = new URL(u, location.origin);
    return p.origin === location.origin
      && (p.searchParams.has("token") || p.searchParams.has("authSig"));
  } catch (e) { return false; }
};

const npArtTouch = (p) => {
  const rec = npArtWarm.get(p);
  if (rec) { npArtWarm.delete(p); npArtWarm.set(p, rec); }
  return rec;
};

// LRU rather than insertion order, so the cover on screen is never the one evicted.
const npArtTrim = () => {
  while (npArtWarm.size > 24) {
    const p = npArtWarm.keys().next().value;
    const rec = npArtWarm.get(p);
    npArtWarm.delete(p);
    if (rec && rec.obj) { try { URL.revokeObjectURL(rec.obj); } catch (e) { /* already gone */ } }
  }
};

const npArtClaim = (u, id) => {
  const p = npArtKey(u, id);
  let rec = npArtTouch(p);
  if (!rec) { rec = {}; npArtWarm.set(p, rec); npArtTrim(); }
  if (rec.obj || rec.busy || rec.tried === u) return rec;
  rec.tried = u;
  if (!npArtRotates(u)) {
    try {
      const im = new Image();
      im.decoding = "async";
      im.src = u;
      rec.img = im;
      if (im.decode) im.decode().catch(() => {});
    } catch (e) { /* no decode support, the img still loads */ }
    return rec;
  }
  rec.busy = true;
  fetch(u, { credentials: "same-origin" })
    .then((r) => (r.ok ? r.blob() : Promise.reject(r.status)))
    .then((b) => {
      const obj = URL.createObjectURL(b);
      // A token rotation is not a repaint, so swap what is already on screen.
      const publish = () => {
        rec.busy = false;
        rec.obj = obj;
        (rec.els || []).forEach((el) => {
          el.style.backgroundImage = "url('" + obj + "')";
        });
        rec.els = null;
      };
      // Decoded first, or the swap off the token URL is a repaint with nothing to show.
      try {
        const im = new Image();
        im.decoding = "async";
        im.src = obj;
        rec.img = im;
        if (im.decode) im.decode().then(publish, publish); else publish();
      } catch (e) { publish(); }
    })
    .catch(() => { rec.busy = false; });
  return rec;
};

const npArt = (src) => {
  if (!src) return "";
  const k = src.key || src.kind || "";
  const id = (src.title || "") + "|" + (src.subtitle || "");
  const cur = src.art || "";
  if (cur) {
    const rec = npArtClaim(cur, id);
    // Until the blob lands, paint the CURRENT url - it is the only one HA serves.
    const u = rec.obj || cur;
    if (k) npArtHold[k] = { id: id, url: u };
    return u;
  }
  if (k) {
    const prev = npArtHold[k];
    // Transient null between polls - hold the last good art, but only within one track.
    if (prev && prev.id === id) return prev.url;
  }
  return "";
};

const npPaintArt = (el, src) => {
  const u = npArt(src);
  if (!el || !u) return u;
  el.style.backgroundImage = "url('" + u + "')";
  const id = ((src && src.title) || "") + "|" + ((src && src.subtitle) || "");
  const rec = npArtWarm.get(npArtKey((src && src.art) || u, id));
  if (rec && rec.busy && !rec.obj) (rec.els || (rec.els = [])).push(el);
  return u;
};

const npSameGame = (x, y) => {
  const flat = (v) => String(v || "").toLowerCase()
    .replace(/[\u2122\u00ae\u00a9]/g, " ")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
  const a = flat(x), b = flat(y);
  if (!a || !b) return false;
  if (a === b) return true;
  const short = a.length <= b.length ? a : b;
  const long = a.length <= b.length ? b : a;
  if (long.indexOf(short + " ") !== 0) return false;
  return !/[0-9]/.test(long.slice(short.length));
};

// The two sources that are a set of entities rather than one.
const npActivitySources = (V, states) => {
  const out = [];
  const norm = (x) => String(x == null ? "" : x).trim();
  const low = (x) => norm(x).toLowerCase();
  const dead = (g) => !g || ["none", "unknown", "unavailable"].includes(g.toLowerCase());
  const started = (id) => {
    const t = id && states[id] && states[id].last_changed;
    const n = t ? Date.parse(t) : NaN;
    return Number.isFinite(n) ? n : 0;
  };
  const NONE = { toggle: false, next: false, prev: false };

  const dcU = V.discord_user && states[V.discord_user];
  const dcA = (dcU && dcU.attributes) || {};
  if (V.discord_user || (V.discord_online && V.discord_game)) {
    // Any presence but offline counts: DND and idle are normal while gaming.
    const status = low(V.discord_online
      ? (states[V.discord_online] || {}).state : (dcU || {}).state);
    const live = !!status
      && !["offline", "unknown", "unavailable", "none"].includes(status);
    const game = norm(V.discord_game
      ? (states[V.discord_game] || {}).state : dcA.game);
    if (live && !dead(game)) {
      const imgS = V.discord_image && states[V.discord_image];
      const ia = (imgS && imgS.attributes) || {};
      const http = (...xs) => xs.find((x) => x && String(x).indexOf("http") === 0) || "";
      const stateUrl = String((imgS || {}).state || "");
      out.push({
        key: "discord", kind: "activity", playing: true,
        art: npAbs(V.discord_image
          ? (ia.entity_picture_local || ia.entity_picture || ia.image_url
            || (/^(https?:)?\/\//.test(stateUrl) || stateUrl.charAt(0) === "/" ? stateUrl : ""))
          : http(dcA.game_image_large, dcA.game_image_header, dcA.game_image_hero_capsule)),
        title: game,
        subtitle: norm(V.discord_details ? (states[V.discord_details] || {}).state
          : (dcA.game_details || dcA.game_state)).replace(/^(unknown|unavailable)$/i, ""),
        source: norm(V.discord_label) || "PC",
        started: started(V.discord_game || V.discord_user),
        controls: NONE,
      });
    }
  }

  // One sensor again: steam_online's account entity carries game and artwork.
  if (V.steam_account || V.steam_game) {
    const stU = V.steam_account && states[V.steam_account];
    const stA = (stU && stU.attributes) || {};
    const status = low((V.steam_online ? states[V.steam_online] : stU || {}).state);
    const live = !(V.steam_account || V.steam_online)
      || (!!status && !["offline", "unknown", "unavailable", "none"].includes(status));
    const game = norm(V.steam_game ? (states[V.steam_game] || {}).state : stA.game);
    if (live && !dead(game)) {
      const imgS = V.steam_image && states[V.steam_image];
      const ia = (imgS && imgS.attributes) || {};
      const http = (...xs) => xs.find((x) => x && String(x).indexOf("http") === 0) || "";
      // An override may be a template sensor whose STATE is the artwork URL.
      const raw = V.steam_image
        ? (ia.entity_picture_local || ia.entity_picture || ia.image_url
           || (String((imgS || {}).state || "").indexOf("http") === 0 ? imgS.state : ""))
        : http(stA.game_image_main, stA.game_image_header, stA.game_icon);
      out.push({
        key: "steam", kind: "activity", playing: true,
        art: npAbs(raw), title: game, subtitle: "",
        source: norm(V.steam_label) || "Steam",
        started: started(V.steam_game || V.steam_account), controls: NONE,
      });
    }
  }
  return out;
};

